/* Fighting-only limb poses, derived from the shared art without mutating it. */
(function(root){'use strict';
const anatomy={explorer:{base:'hero',walk:'walk',jump:'jump',left:6,right:10,arm:8,armEnd:11,hip:12,legs:13,sleeve:'R',pants:'B',shoe:'H'},soldier:{base:'soldier',walk:'soldierWalk',jump:'soldierJump',left:6,right:10,arm:8,armEnd:14,hip:16,legs:17,sleeve:'S',pants:'B',shoe:'H'},mystic:{base:'mystic',walk:'mysticWalk',jump:'mysticJump',left:5,right:10,arm:12,armEnd:14,hip:17,legs:18,sleeve:'B',pants:'B',shoe:'H'},dora:{base:'dora',walk:'doraWalk',jump:'dora',left:7,right:16,arm:16,armEnd:17,hip:20,legs:22,sleeve:'B',pants:'B',shoe:'W'},goku:{base:'goku',walk:'gokuWalk',jump:'goku',left:6,right:13,arm:11,armEnd:14,hip:17,legs:18,sleeve:'R',pants:'R',shoe:'B'},nezha:{base:'nezha',walk:'nezhaWalk',jump:'nezha',left:6,right:13,arm:13,armEnd:15,hip:17,legs:18,sleeve:'R',pants:'V',shoe:'S'}};
function create(assets){const sets={};for(const [id,cfg] of Object.entries(anatomy)){const pad=12,width=52,anchor=pad+(cfg.left+cfg.right)/2;function grid(name){return assets.art[name].map((row,y)=>{const out=Array(width).fill('.');for(let x=0;x<row.length;x++)out[pad+x]=row[x];if(id==='soldier'){for(let x=0;x<width;x++)if(out[x]==='G'&&y>=9&&y<=14)out[x]=x>=pad+cfg.left&&x<=pad+cfg.right?'W':'.';}return out;});}
function paint(g,x,y,w,h,ch){for(let yy=Math.round(y);yy<Math.round(y)+h;yy++)for(let xx=Math.round(x);xx<Math.round(x)+w;xx++)if(g[yy]&&xx>=0&&xx<width)g[yy][xx]=ch;}
function line(g,x,y,tx,ty,w,ch){const steps=Math.ceil(Math.hypot(tx-x,ty-y)*2);for(let i=0;i<=steps;i++){const q=steps?i/steps:0;paint(g,x+(tx-x)*q-w/2,y+(ty-y)*q-w/2,w,w,ch);}}
function arms(g,extension=0){for(let y=cfg.arm;y<=cfg.armEnd;y++)for(let x=0;x<width;x++)if(x<pad+cfg.left||x>pad+cfg.right){if(id!=='nezha'||g[y][x]!=='P')g[y][x]='.';}const shoulder=pad+cfg.right-1,y=cfg.arm+1,skin=id==='dora'?'W':'S';line(g,pad+cfg.left,y,pad+cfg.left-2,y+3,2,cfg.sleeve);paint(g,pad+cfg.left-3,y+2,2,2,skin);const elbow=shoulder+2+extension*3,ey=y+3-extension*3,tip=shoulder+2+extension*(id==="dora"?5:7),ty=y+3-extension*3;line(g,shoulder,y,elbow,ey,2,cfg.sleeve);line(g,elbow,ey,tip,ty,2,skin);paint(g,tip-1,ty-1,3,3,skin);if(id!=='dora')paint(g,tip,ty+1,2,1,'T');}
function frame(g){return {rows:g.map(row=>row.join('')),anchor};}
sets[id]={idle:[],run:[],jump:[],punch:[],kick:[]};for(const [action,name] of [['idle',cfg.base],['run',cfg.walk],['jump',cfg.jump]]){const g=grid(name);if(id==='soldier')arms(g,0);sets[id][action].push(frame(g));}sets[id].run.unshift(sets[id].idle[0]);
for(const extent of [0,.45,1,.45,0]){const g=grid(cfg.base);arms(g,extent);sets[id].punch.push(frame(g));}
for(const extent of [0,.35,1,.5,0]){const g=grid(cfg.base);arms(g,0);for(let y=cfg.legs;y<g.length;y++)g[y].fill('.');const h=g.length-1,hip=anchor,y=cfg.hip;line(g,hip-2,y,hip-3,h-2,3,cfg.pants);paint(g,hip-5,h-1,4,2,cfg.shoe);const kx=hip+3+extent*4,ky=y+3-extent*4,fx=hip+3+extent*(id==="dora"?4:id==="explorer"?6:8),fy=h-2-extent*(h-y+1);line(g,hip+1,y,kx,ky,3,cfg.pants);line(g,kx,ky,fx,fy,2,cfg.pants);paint(g,fx-1,fy-1,4,2,cfg.shoe);sets[id].kick.push(frame(g));}
}return sets;}
let frames;function draw(c,p,t,assets){frames??=create(assets);const sets=frames[p.id],a=p.action;let group=!p.ground?'jump':Math.abs(p.vx)>20?'run':'idle',index=group==='run'?Math.floor(t*10)%2:0;if(a&&['light','heavy'].includes(a.kind)){group=a.kind==='light'?'punch':'kick';index=a.t<=a.start?Math.min(2,Math.floor(a.t/a.start*3)):Math.min(4,3+Math.floor((a.t-a.start)/(a.duration-a.start)*2));}const f=sets[group][index],scale=96/f.rows.length,palette={...assets.palette,...assets.colors[p.id]};c.save();c.translate(p.x,p.y);if(p.roll>0){c.translate(0,-48);c.rotate(p.rollDirection*(1-p.roll/.38)*Math.PI*2);c.translate(0,48);}if(p.invincible>0)c.globalAlpha=Math.floor(t*14)%2?.35:1;else if(p.dodgeFlash>0)c.globalAlpha=.45;else if(p.flash>0)c.globalAlpha=.65;c.scale(p.facing<0?-scale:scale,scale);for(let y=0;y<f.rows.length;y++)for(let x=0;x<f.rows[y].length;x++){const ch=f.rows[y][x];if(ch!=='.'){c.fillStyle=palette[ch]||'#fff';c.fillRect(x-f.anchor,y-f.rows.length,1,1);}}c.restore();return 96;}
const api={create,draw};root.PixelFightingSprites=api;if(typeof module==='object')module.exports=api;
})(globalThis);
